self.KB_CONTENT["card:717057"]={"id":"card:717057","ty":"card","sourceId":"717057","title":"『專案代號建立作業-EPMI14』不取消確認的情況下，如何修改預計的工程日期？","ver":"GP40","topic":"epmi","keywords":["epmi","結案","預計","專案"],"y":"howto","answer":"點工具列【工程進度(預計)】後，即可修改【預計竣工日】、【預計驗收日】、【預計結案日】、【預計失效日】。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
