self.KB_CONTENT["card:752137"]={"id":"card:752137","ty":"card","sourceId":"752137","title":"『合併報表基本資料拋轉作業』中的『拋轉關係人會計科目各期餘額檔』為何？","ver":"iGP","topic":"科目","keywords":["科目","拋轉","合併","餘額"],"y":"other","answer":"* 指是否將關係人會計科目各期餘額檔拋轉至母公司主機。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
