self.KB_CONTENT["card:750733"]={"id":"card:750733","ty":"card","sourceId":"750733","title":"『逾期應收帳款明細表』中的『最少逾期天數』為何？","ver":"iGP","topic":"明細表","keywords":["明細表","應收","帳款","月底"],"y":"other","answer":"* 此欄位不可小於零。預設為0。※ 應收帳款月底重評價表","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
