self.KB_CONTENT["card:757376"]={"id":"card:757376","ty":"card","sourceId":"757376","title":"『進貨單建立作業』中的『數量合計 (TG026)』為何？","ver":"iGP","topic":"進貨單","keywords":["進貨單","單身","單位","製造"],"y":"other","answer":"* 為單身驗收數量累計。* 數量表達方式之『共用參數設定作業』為「單一單位」或「製造雙單位」時，加總單身數量。* 數量表達方式之『共用參數設定作業』非「雙單位」時，加總單身數量的整數數量。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
