self.KB_CONTENT["field:753633"]={"id":"field:753633","ty":"field","sourceId":"753633","title":"課稅別","ver":"iGP","topic":"","keywords":[],"job":"客戶訂單建立作業","code":"TC016","answer":"* 此欄位僅作顯示，取稅別碼設定作業上的課稅別，欲變更請重新選擇稅別碼。* 應為以下幾種之一1.應稅內含、2.應稅外加、3.零稅率、4.免稅及9.不計稅。","file":"fields.jsonl"};
